import gdb,struct
p=gdb.selected_inferior();base=0x7f5b324b0000
for name,offset in [('lock_import',0xb70b8),('unlock_import',0xb70c0),('parked_head',0xbf368)]:
 x=struct.unpack('<Q',p.read_memory(base+offset,8).tobytes())[0];print(name,hex(x),'offset_from_kernel',hex(x-base))
 print('PC',hex(x))
 if name!='parked_head':
  try:print('CODE',p.read_memory(x,16).tobytes().hex())
  except Exception as e:print(e)
